Set-StrictMode -Version Latest
function New-Cmd($c,$sql,$p=@{}){$x=$c.CreateCommand();$x.CommandText=$sql;foreach($k in $p.Keys){$q=$x.CreateParameter();$q.ParameterName="@$k";$q.Value=if($null-eq$p[$k]){[DBNull]::Value}else{$p[$k]};[void]$x.Parameters.Add($q)};$x}
function Ensure-OfflineSyncStore($DbConnection,[bool]$IsSqlServer){if(-not$IsSqlServer){return};$sql="IF OBJECT_ID('dbo.BridgeOfflineVoucherSync','U') IS NULL CREATE TABLE dbo.BridgeOfflineVoucherSync(Id BIGINT IDENTITY PRIMARY KEY,LocalId VARCHAR(100) NOT NULL,InstanceId VARCHAR(100) NOT NULL,CompanyCode VARCHAR(50) NOT NULL,VchType INT NOT NULL,SeriesName VARCHAR(100),TemporaryVchNo VARCHAR(100),FinalVchNo VARCHAR(100),Status VARCHAR(20) NOT NULL,RequestPayload NVARCHAR(MAX),ErrorMessage NVARCHAR(2000),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),SyncedAt DATETIME2,CONSTRAINT UQ_BridgeOfflineVoucherSync UNIQUE(LocalId,InstanceId,CompanyCode))";$c=New-Cmd $DbConnection $sql;try{[void]$c.ExecuteNonQuery()}finally{$c.Dispose()}}
function Get-OfflineSyncRecord($DbConnection,[bool]$IsSqlServer,$LocalId,$InstanceId,$CompanyCode){$t=if($IsSqlServer){'dbo.BridgeOfflineVoucherSync'}else{'BridgeOfflineVoucherSync'};$c=New-Cmd $DbConnection "SELECT TOP 1 * FROM $t WHERE LocalId=@LocalId AND InstanceId=@InstanceId AND CompanyCode=@CompanyCode" @{LocalId=$LocalId;InstanceId=$InstanceId;CompanyCode=$CompanyCode};try{$r=$c.ExecuteReader();try{if(-not$r.Read()){return$null};$o=@{};for($i=0;$i-lt$r.FieldCount;$i++){$o[$r.GetName($i)]=if($r.IsDBNull($i)){$null}else{$r.GetValue($i)}};[pscustomobject]$o}finally{$r.Dispose()}}finally{$c.Dispose()}}
function Add-OfflineSyncPendingRecord($DbConnection,[bool]$IsSqlServer,$Data){$t=if($IsSqlServer){'dbo.BridgeOfflineVoucherSync'}else{'BridgeOfflineVoucherSync'};$now=if($IsSqlServer){'SYSDATETIME()'}else{'Now()'};$c=New-Cmd $DbConnection "INSERT INTO $t(LocalId,InstanceId,CompanyCode,VchType,SeriesName,TemporaryVchNo,Status,RequestPayload,CreatedAt) VALUES(@LocalId,@InstanceId,@CompanyCode,@VchType,@SeriesName,@TemporaryVchNo,'PROCESSING',@RequestPayload,$now)" @{LocalId=$Data.localId;InstanceId=$Data.instanceId;CompanyCode=$Data.companyCode;VchType=[int]$Data.vchType;SeriesName=$Data.seriesName;TemporaryVchNo=$Data.temporaryVchNo;RequestPayload=($Data|ConvertTo-Json -Depth 100 -Compress)};try{[void]$c.ExecuteNonQuery()}finally{$c.Dispose()}}
function Complete-OfflineSyncRecord($DbConnection,[bool]$IsSqlServer,$Data,$FinalVchNo){$t=if($IsSqlServer){'dbo.BridgeOfflineVoucherSync'}else{'BridgeOfflineVoucherSync'};$now=if($IsSqlServer){'SYSDATETIME()'}else{'Now()'};$c=New-Cmd $DbConnection "UPDATE $t SET Status='SYNCED',FinalVchNo=@FinalVchNo,ErrorMessage=NULL,SyncedAt=$now WHERE LocalId=@LocalId AND InstanceId=@InstanceId AND CompanyCode=@CompanyCode" @{FinalVchNo=$FinalVchNo;LocalId=$Data.localId;InstanceId=$Data.instanceId;CompanyCode=$Data.companyCode};try{[void]$c.ExecuteNonQuery()}finally{$c.Dispose()}}
function Fail-OfflineSyncRecord($DbConnection,[bool]$IsSqlServer,$Data,$ErrorMessage){$t=if($IsSqlServer){'dbo.BridgeOfflineVoucherSync'}else{'BridgeOfflineVoucherSync'};$c=New-Cmd $DbConnection "UPDATE $t SET Status='FAILED',ErrorMessage=@ErrorMessage WHERE LocalId=@LocalId AND InstanceId=@InstanceId AND CompanyCode=@CompanyCode" @{ErrorMessage=$ErrorMessage;LocalId=$Data.localId;InstanceId=$Data.instanceId;CompanyCode=$Data.companyCode};try{[void]$c.ExecuteNonQuery()}finally{$c.Dispose()}}
